/**
 * Normalise the files generated by `npx shadcn@latest add @reui/c-data-grid-32`.
 *
 * The ReUI registry is authored against a demo app, so the generated files carry
 * three things this project cannot use as-is:
 *
 * 1. `@tanstack/react-table` / `@tanstack/react-virtual` — ReUI targets TanStack
 *    **v9**, while 27 existing files here use v8.10.7. Both are installed, with
 *    v9 under the `-v9` npm aliases, so this script points the generated grid at
 *    the aliases and leaves every v8 consumer untouched.
 * 2. `from "cn"` — a registry-only module name meaning "this project's `cn`
 *    helper". It maps to `~/lib/utils`.
 * 3. `@/app/(create)/components/icon-placeholder` — a placeholder that only
 *    exists inside ReUI's own demo. It is swapped for a real `lucide-react` icon
 *    with the same props signature.
 *
 * Idempotent: running it twice is a no-op.
 *
 *   node scripts/fix-reui-imports.mjs
 */
import { readFileSync, readdirSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";

const TARGET_DIRS = ["src/components/reui", "src/components/examples"];

/**
 * Placeholder icon → lucide equivalent. `IconPlaceholder` is rendered as both
 * `<IconPlaceholder />` and `<IconPlaceholder className="…" />`, so keeping a
 * component-shaped shim is less invasive than rewriting each call site.
 */
const ICON_SHIM = `const IconPlaceholder = ({ className }: { className?: string }) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth={2}
    strokeLinecap="round"
    strokeLinejoin="round"
    className={className}
    aria-hidden="true"
  >
    <path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z" />
    <path d="M14 2v4a2 2 0 0 0 2 2h4" />
  </svg>
)
`;

/** [pattern, replacement]; `$1` in the replacement is filled from the capture. */
/** @type {Array<[RegExp, string]>} */
const RULES = [
  // TanStack v9 aliases (must run before any other TanStack rewrite).
  [/\bfrom\s+"@tanstack\/react-table"/g, 'from "@tanstack/react-table-v9"'],
  [/\bfrom\s+"@tanstack\/react-virtual"/g, 'from "@tanstack/react-virtual-v9"'],
  // Registry-only `cn` module.
  [/\bfrom\s+"cn"/g, 'from "~/lib/utils"'],
  // The shadcn CLI maps `@/components/ui/*` onto this project's *shared*
  // primitives (`~/components/shadcn/*`), which are Radix-based and styled for
  // the whole app. The grid needs its own copies — extra button sizes, an
  // `indeterminate` checkbox, Base UI composition props — so it resolves to the
  // grid-local namespace and leaves the shared primitives untouched.
  [
    /\bfrom\s+"~\/components\/shadcn\/([a-z-]+)"/g,
    'from "~/components/reui/ui/$1"',
  ],
  // Demo-only icon placeholder.
  [
    /^import\s*\{\s*IconPlaceholder\s*\}\s*from\s*"@\/app\/\(create\)\/components\/icon-placeholder"\s*;?\s*$/gm,
    ICON_SHIM,
  ],
];

function walk(dir, out = []) {
  if (!existsSync(dir)) return out;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) walk(path, out);
    else if (/\.tsx?$/.test(entry.name)) out.push(path);
  }
  return out;
}

let changed = 0;
for (const dir of TARGET_DIRS) {
  for (const file of walk(dir)) {
    const before = readFileSync(file, "utf8");
    let after = before;
    for (const [pattern, replacement] of RULES) {
      after = after.replace(pattern, (match, ...rest) => {
        const group = rest[0];
        if (typeof group !== "string") return replacement;
        return replacement.replace("$1", group);
      });
    }
    if (after !== before) {
      writeFileSync(file, after);
      changed += 1;
      console.log("rewrote", file);
    }
  }
}

console.log(changed ? `${changed} file(s) rewritten.` : "Nothing to do — already normalised.");
